export function useDesignAppSelectedConnector(id?: DesignAppId): SelectedConnector {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const designScope = useDesignScope();
  const kitGuid = kitScope?.guid ?? id?.kit ?? "";
  const designGuid = designScope?.guid ?? id?.design ?? "";
  const selector = useMemo(() => {
    const key = `${kitGuid}:${designGuid}`;
    return (state: { context: SketchpadContext }) => {
      const connector = state.context.designApps[key]?.selection?.connectors?.[0];
      if (!connector?.piece || !connector?.connector) return EMPTY_CONNECTOR;
      return connector;
    };
  }, [kitGuid, designGuid]);
  const raw = useSelector(actor, selector);
  const lastRef = useRef<SelectedConnector>(EMPTY_CONNECTOR);
  if (!raw) {
    lastRef.current = EMPTY_CONNECTOR;
    return EMPTY_CONNECTOR;
  }
  if (lastRef.current && lastRef.current.piece === raw.piece && lastRef.current.connector === raw.connector) {
    return lastRef.current;
  }
  const result: SelectedConnector = { piece: raw.piece, connector: raw.connector };
  lastRef.current = result;
  return result;
}

